-- <auto-generated />
-- Generated from Godswar Origin AddressConfig.ini, MapIdToNameConfig.ini, Scenes.dat, MapSoundConfig.xml, SpanMapConfig.xml, and map Address.ini files.
CREATE TABLE IF NOT EXISTS map_templates (
    map_id smallint PRIMARY KEY,
    scene_key varchar(96) NOT NULL,
    display_name varchar(128) NOT NULL DEFAULT '',
    client_scene_id integer,
    map_mode smallint,
    address_file varchar(255) NOT NULL DEFAULT '',
    music_name varchar(128) NOT NULL DEFAULT '',
    event_scene_key varchar(128) NOT NULL DEFAULT '',
    stats jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS ix_map_templates_scene_key ON map_templates (scene_key);
CREATE INDEX IF NOT EXISTS ix_map_templates_client_scene_id ON map_templates (client_scene_id);

ON CONFLICT (map_id) DO UPDATE
SET scene_key = EXCLUDED.scene_key,
    display_name = EXCLUDED.display_name,
    client_scene_id = EXCLUDED.client_scene_id,
    map_mode = EXCLUDED.map_mode,
    address_file = EXCLUDED.address_file,
    music_name = EXCLUDED.music_name,
    event_scene_key = EXCLUDED.event_scene_key,
    stats = EXCLUDED.stats;

CREATE TABLE IF NOT EXISTS map_safe_areas (
    map_id smallint NOT NULL REFERENCES map_templates(map_id) ON DELETE CASCADE,
    area_index smallint NOT NULL,
    x1 real NOT NULL,
    z1 real NOT NULL,
    x2 real NOT NULL,
    z2 real NOT NULL,
    attribute smallint,
    PRIMARY KEY (map_id, area_index)
);

ON CONFLICT (map_id, area_index) DO UPDATE
SET x1 = EXCLUDED.x1,
    z1 = EXCLUDED.z1,
    x2 = EXCLUDED.x2,
    z2 = EXCLUDED.z2,
    attribute = EXCLUDED.attribute;

CREATE TABLE IF NOT EXISTS map_address_points (
    map_id smallint NOT NULL REFERENCES map_templates(map_id) ON DELETE CASCADE,
    group_index smallint NOT NULL,
    point_index smallint NOT NULL,
    group_name varchar(128) NOT NULL DEFAULT '',
    name varchar(128) NOT NULL DEFAULT '',
    pos_x real NOT NULL,
    pos_z real NOT NULL,
    source varchar(255) NOT NULL DEFAULT '',
    PRIMARY KEY (map_id, group_index, point_index)
);

CREATE INDEX IF NOT EXISTS ix_map_address_points_name ON map_address_points (name);

ON CONFLICT (map_id, group_index, point_index) DO UPDATE
SET group_name = EXCLUDED.group_name,
    name = EXCLUDED.name,
    pos_x = EXCLUDED.pos_x,
    pos_z = EXCLUDED.pos_z,
    source = EXCLUDED.source;

CREATE TABLE IF NOT EXISTS map_links (
    map_id smallint NOT NULL REFERENCES map_templates(map_id) ON DELETE CASCADE,
    link_index smallint NOT NULL,
    target_map_id smallint NOT NULL,
    pos_x real NOT NULL,
    pos_z real NOT NULL,
    source varchar(64) NOT NULL DEFAULT '',
    PRIMARY KEY (map_id, link_index, target_map_id)
);

CREATE INDEX IF NOT EXISTS ix_map_links_target ON map_links (target_map_id);

ON CONFLICT (map_id, link_index, target_map_id) DO UPDATE
SET pos_x = EXCLUDED.pos_x,
    pos_z = EXCLUDED.pos_z,
    source = EXCLUDED.source;

CREATE TABLE IF NOT EXISTS map_routes (
    camp smallint NOT NULL,
    route_index smallint NOT NULL,
    map_ids smallint[] NOT NULL DEFAULT '{}',
    source varchar(64) NOT NULL DEFAULT '',
    PRIMARY KEY (camp, route_index)
);

ON CONFLICT (camp, route_index) DO UPDATE
SET map_ids = EXCLUDED.map_ids,
    source = EXCLUDED.source;

CREATE OR REPLACE VIEW map_template_summary AS
SELECT
    mt.map_id,
    mt.scene_key,
    mt.display_name,
    mt.client_scene_id,
    mt.map_mode,
    mt.music_name,
    mt.event_scene_key,
    COUNT(DISTINCT msa.area_index) AS safe_area_count,
    COUNT(DISTINCT map.group_index || ':' || map.point_index) AS address_point_count,
    COUNT(DISTINCT ml.link_index || ':' || ml.target_map_id) AS link_count
FROM map_templates mt
LEFT JOIN map_safe_areas msa ON msa.map_id = mt.map_id
LEFT JOIN map_address_points map ON map.map_id = mt.map_id
LEFT JOIN map_links ml ON ml.map_id = mt.map_id
GROUP BY mt.map_id, mt.scene_key, mt.display_name, mt.client_scene_id, mt.map_mode, mt.music_name, mt.event_scene_key;
